create table characters(id uuid primary key default gen_random_uuid(),series_id uuid not null references series(id) on delete cascade,code text not null,name text not null,role_type text not null default 'CORE',species text not null,personality jsonb not null default '{}'::jsonb,status text not null default 'DRAFT',created_at timestamptz not null default now(),unique(series_id,code));
create table voices(id uuid primary key default gen_random_uuid(),character_id uuid references characters(id) on delete cascade,provider text not null default 'elevenlabs',provider_voice_id text,model text,language text not null default 'hu',settings jsonb not null default '{}'::jsonb,status text not null default 'DRAFT',created_at timestamptz not null default now());
alter table characters add column voice_id uuid references voices(id);
create table character_versions(id uuid primary key default gen_random_uuid(),character_id uuid not null references characters(id) on delete cascade,version int not null check(version>0),model_asset_id uuid references assets(id),rig_asset_id uuid references assets(id),facial_profile jsonb not null default '{}'::jsonb,default_costume_code text,scale_cm numeric,status text not null default 'DRAFT',locked_at timestamptz,created_at timestamptz not null default now(),unique(character_id,version));
create table locations(id uuid primary key default gen_random_uuid(),series_id uuid not null references series(id) on delete cascade,code text not null,name text not null,status text not null default 'DRAFT',created_at timestamptz not null default now(),unique(series_id,code));
create table location_versions(id uuid primary key default gen_random_uuid(),location_id uuid not null references locations(id) on delete cascade,version int not null check(version>0),blend_asset_id uuid references assets(id),metadata jsonb not null default '{}'::jsonb,status text not null default 'DRAFT',created_at timestamptz not null default now(),unique(location_id,version));
create table animations(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,category text not null,source_asset_id uuid references assets(id),skeleton_profile text,duration_sec numeric check(duration_sec is null or duration_sec>0),loopable boolean not null default false,metadata jsonb not null default '{}'::jsonb,status text not null default 'DRAFT',created_at timestamptz not null default now());
create table dialogue_lines(id uuid primary key default gen_random_uuid(),episode_id uuid not null references episodes(id) on delete cascade,scene_id uuid references scenes(id) on delete cascade,shot_id uuid references shots(id) on delete set null,character_id uuid not null references characters(id),sequence_no int not null check(sequence_no>0),text text not null,emotion text not null default 'NEUTRAL',voice_asset_id uuid references assets(id),duration_sec numeric check(duration_sec is null or duration_sec>0),status text not null default 'DRAFT',created_at timestamptz not null default now());
create index characters_series_idx on characters(series_id); create index voices_character_idx on voices(character_id); create index character_versions_character_idx on character_versions(character_id); create index locations_series_idx on locations(series_id); create index location_versions_location_idx on location_versions(location_id); create index dialogue_episode_seq_idx on dialogue_lines(episode_id,sequence_no);
alter table characters enable row level security; alter table voices enable row level security; alter table character_versions enable row level security; alter table locations enable row level security; alter table location_versions enable row level security; alter table animations enable row level security; alter table dialogue_lines enable row level security;